package com.bridge.quartercore;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FixedEIdleBaselineTest {
 @Test void separateVerifiedBaseAndExactlyTwoPairs(){var base=FixedEIdleBaseline.snapshot();assertEquals(FixedEIdleBaseline.TOKEN,JournalSessionAuthority.fullToken(base));assertNotEquals(FixedERestartPreflight.INITIAL_TOKEN,JournalSessionAuthority.fullToken(base));var bundle=FixedEBaselineBundle.compiledIdleWake();assertEquals(0,bundle.completedPairs(base));bundle.requireNextClaim(base);var one=FixedERestartHttpSafetyTest.pair(base,"w-"+UUID.randomUUID());assertEquals(1,bundle.completedPairs(one));bundle.requireNextClaim(one);var two=FixedERestartHttpSafetyTest.pair(one,"w-"+UUID.randomUUID());assertEquals(2,bundle.completedPairs(two));assertThrows(RuntimeException.class,()->bundle.requireNextClaim(two));var third=FixedERestartHttpSafetyTest.pair(two,"w-"+UUID.randomUUID());assertThrows(RuntimeException.class,()->bundle.completedPairs(third));assertThrows(RuntimeException.class,()->bundle.completedPairs(FixedECompiledBaseline.snapshot()));assertEquals(0,FixedEBaselineBundle.compiled().completedPairs(FixedECompiledBaseline.snapshot()));assertEquals(NativeRestartCompiledRelease.pendingReview().binding(),NativeRestartCompiledRelease.require().binding());var artifact=FixedEVerifiedArtifact.completedIdleWake();artifact.verifyOnce(()->two);assertNotNull(artifact.response("GET",FixedEVerifiedArtifact.PATH,null));}
 @Test void defaultDisabledAndFormalSettingsNeverChooseTarget(){assertThrows(RuntimeException.class,()->FixedEBoundedRestartMain.requireIdleConfiguration(Map.of()));var e=new HashMap<String,String>();e.put("BRIDGE_FIXED_E_IDLE_WAKE_ENABLED","true");e.put("BRIDGE_READONLY_STARTUP_ENABLED","false");e.put("BRIDGE_DATASET_ID","formal-unused");assertDoesNotThrow(()->FixedEBoundedRestartMain.requireIdleConfiguration(e));e.put("BRIDGE_FIXED_E_BASELINE","caller");assertThrows(RuntimeException.class,()->FixedEBoundedRestartMain.requireIdleConfiguration(e));}
 @Test void originalArtifactLoaderCannotBeRetargetedToNewArtifact()throws Exception{try(var in=getClass().getResourceAsStream(FixedEIdleBaseline.RESOURCE)){assertThrows(RuntimeException.class,()->FixedECompiledBaseline.decode(in.readAllBytes()));}var originalArtifact=FixedEVerifiedArtifact.initial();assertThrows(RuntimeException.class,()->originalArtifact.verifyOnce(FixedEIdleBaseline::snapshot));}
 @Test void changedProjectionAndUnstartedCompletionRejected(){var bad=FixedEIdleBaseline.snapshot();bad.sheet("accounts").rows.get(1).set(1,"tamper");assertThrows(RuntimeException.class,()->FixedEBaselineBundle.compiledIdleWake().requireNextClaim(bad));var artifact=FixedEVerifiedArtifact.completedIdleWake();assertThrows(RuntimeException.class,()->artifact.verifyOnce(FixedEIdleBaseline::snapshot));assertNull(artifact.response("GET",FixedEVerifiedArtifact.PATH,null));}
}
